package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonIntegerFormatVisitor;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonNumberFormatVisitor;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.std.NumberSerializers.DoubleSerializer;
import com.fasterxml.jackson.databind.ser.std.TypeSerializer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;

public class DoubleSerializer_serializeWithType_TriageGen1Test {

    private DoubleSerializer doubleSerializer;
    private JsonGenerator jsonGenerator;
    private SerializerProvider serializerProvider;
    private TypeSerializer typeSerializer;

    @Before
    public void setUp() {
        // We use a spy on the actual object to verify that serializeWithType calls serialize()
        doubleSerializer = spy(new DoubleSerializer());
        jsonGenerator = Mockito.mock(JsonGenerator.class);
        serializerProvider = Mockito.mock(SerializerProvider.class);
        typeSerializer = Mockito.mock(TypeSerializer.class);
    }

    @Test
    public void testSerializeWithType_Success() throws IOException {
        // Arrange
        Object value = 1.23;
        doNothing().when(doubleSerializer).serialize(eq(value), eq(jsonGenerator), eq(serializerProvider));

        // Act
        doubleSerializer.serializeWithType(value, jsonGenerator, serializerProvider, typeSerializer);

        // Assert
        // Verify that serializeWithType calls the internal serialize method correctly
        verify(doubleSerializer).serialize(value, jsonGenerator, serializerProvider);
    }

    @Test(expected = IOException.class)
    public void testSerializeWithType_ThrowsIOException() throws IOException {
        // Arrange
        Object value = 1.23;
        doThrow(new IOException("Simulated IOException"))
                .when(doubleSerializer).serialize(eq(value), eq(jsonGenerator), eq(serializerProvider));

        // Act
        doubleSerializer.serializeWithType(value, jsonGenerator, serializerProvider, typeSerializer);

        // Assert - Handled by expected exception
    }

    @Test
    public void testSerializeWithType_NullValue() throws IOException {
        // Arrange
        Object value = null;
        doNothing().when(doubleSerializer).serialize(eq(null), eq(jsonGenerator), eq(serializerProvider));

        // Act
        doubleSerializer.serializeWithType(value, jsonGenerator, serializerProvider, typeSerializer);

        // Assert
        verify(doubleSerializer).serialize(null, jsonGenerator, serializerProvider);
    }
}
